# ==================== 自动清理无效演示 Cookie 与残留文件 ====================
def cleanup_fake_demo_cookie():
    """如果检测到本地 cookies.txt 中包含之前前端演示用的假 SESSDATA (8a92f10c...)，自动清除以免误导"""
    if COOKIES_FILE.exists():
        try:
            content = COOKIES_FILE.read_text(encoding="utf-8", errors="ignore")
            if "8a92f10c" in content or "384920192" in content:
                COOKIES_FILE.unlink()
                print("[安全清理] 已自动移除无效的演示占位 Cookie，请使用手机扫码或粘贴真实 Cookie。")
        except Exception:
            pass


def cleanup_residual_html_files(folder_path=None):
    target_dir = Path(folder_path) if folder_path else DEFAULT_DOWNLOAD_DIR
    if target_dir.exists() and target_dir.is_dir():
        for f in target_dir.iterdir():
            if f.is_file() and f.suffix.lower() in JUNK_EXTENSIONS:
                try:
                    f.unlink()
                except Exception:
                    pass


# ==================== B站官方 API 验证与扫码登录实现 ====================
def parse_cookie_dict_from_file():
    res = {}
    if not COOKIES_FILE.exists():
        return res
    try:
        for line in COOKIES_FILE.read_text(encoding="utf-8", errors="ignore").splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split("\t")
            if len(parts) >= 7:
                res[parts[5].strip()] = parts[6].strip()
    except Exception:
        pass
    return res


def verify_bilibili_cookie():
    """请求 B站官方 nav 接口，验证当前保存的 cookies.txt 是否真实登录以及是否拥有大会员"""
    cookies = parse_cookie_dict_from_file()
    if not cookies.get("SESSDATA"):
        return {"isLogin": False, "message": "未包含 SESSDATA"}
    if "8a92f10c" in cookies.get("SESSDATA", ""):
        return {"isLogin": False, "message": "当前为演示假数据，非真实账号"}

    cookie_header = "; ".join(f"{k}={v}" for k, v in cookies.items())
    req = urllib.request.Request(
        "https://api.bilibili.com/x/web-interface/nav",
        headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
            "Referer": "https://www.bilibili.com/",
            "Cookie": cookie_header
        }
    )
    try:
        with urllib.request.urlopen(req, timeout=8) as resp:
            payload = json.loads(resp.read().decode("utf-8"))
            data = payload.get("data") or {}
            if payload.get("code") == 0 and data.get("isLogin"):
                vip_status = int(data.get("vipStatus") or 0) == 1
                return {
                    "isLogin": True,
                    "uname": data.get("uname", "B站用户"),
                    "mid": data.get("mid", ""),
                    "isVip": vip_status,
                    "vipLabel": (data.get("vip_label") or {}).get("text", "大会员" if vip_status else "普通用户")
                }
            return {"isLogin": False, "message": payload.get("message", "Cookie 已失效或未登录")}
    except Exception as e:
        return {"isLogin": False, "message": str(e)}


def generate_bilibili_qr():
    req = urllib.request.Request(
        "https://passport.bilibili.com/x/passport-login/web/qrcode/generate",
        headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
            "Referer": "https://www.bilibili.com/"
        }
    )
    with urllib.request.urlopen(req, timeout=8) as resp:
        payload = json.loads(resp.read().decode("utf-8"))
        data = payload.get("data") or {}
        return {"ok": True, "url": data.get("url"), "qrcode_key": data.get("qrcode_key")}


def poll_bilibili_qr(qrcode_key):
    cj = http.cookiejar.CookieJar()
    opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(cj))
    poll_url = f"https://passport.bilibili.com/x/passport-login/web/qrcode/poll?qrcode_key={urllib.parse.quote(qrcode_key)}"
    req = urllib.request.Request(
        poll_url,
        headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
            "Referer": "https://www.bilibili.com/"
        }
    )
    with opener.open(req, timeout=8) as resp:
        payload = json.loads(resp.read().decode("utf-8"))
        data = payload.get("data") or {}
        code = data.get("code", -1)
        if code == 0:
            # 登录成功！从返回 URL 参数与 CookieJar 中提取全部真實 Cookie 并转成 Netscape 格式
            lines = ["# Netscape HTTP Cookie File", "# Generated by Bilibili Official QR Login"]
            exp = int(time.time()) + 86400 * 180
            extracted = {}
            for c in cj:
                extracted[c.name] = c.value
            redirect_url = data.get("url", "")
            if "?" in redirect_url:
                qs = urllib.parse.parse_qs(redirect_url.split("?", 1)[1])
                for k, v_list in qs.items():
                    if k in ("SESSDATA", "bili_jct", "DedeUserID", "DedeUserID__ckMd5", "sid") and v_list:
                        extracted[k] = urllib.parse.quote(v_list[0], safe="*")
            for k, v in extracted.items():
                lines.append(f".bilibili.com\tTRUE\t/\tTRUE\t{exp}\t{k}\t{v}")
            cookie_text = "\n".join(lines) + "\n"
            COOKIES_FILE.write_text(cookie_text, encoding="utf-8")
            cfg = load_json_file(CONFIG_FILE, {})
            cfg["cookie_mode"] = "file"
            save_json_file(CONFIG_FILE, cfg)
            return {"ok": True, "code": 0, "cookieText": cookie_text}
        return {"ok": True, "code": code, "message": data.get("message", "")}


# ==================== 内置 yt-dlp 与 FFmpeg 组件管理 ====================
def resolve_ytdlp_executable():
    if LOCAL_YTDLP_PATH.exists():
        return str(LOCAL_YTDLP_PATH)
    cwd_bin = Path.cwd() / YTDLP_BIN_NAME
    if cwd_bin.exists():
        return str(cwd_bin)
    sys_bin = shutil.which("yt-dlp")
    if sys_bin:
        return sys_bin
    return None


def resolve_ffmpeg_executable():
    if LOCAL_FFMPEG_PATH.exists():
        return str(LOCAL_FFMPEG_PATH)
    sys_ff = shutil.which("ffmpeg")
    if sys_ff:
        return sys_ff
    return None


def ensure_ffmpeg_installed(log_fn=print):
    """确保本地存在 ffmpeg（B站 1080P/4K 音视频合并必备组件）"""
    existing = resolve_ffmpeg_executable()
    if existing:
        return existing
    if not IS_WIN:
        return None
    try:
        log_fn("[FFmpeg组件] 检测到系统未安装 FFmpeg（B站 1080P/4K 音画合并必需），正在自动下载内置 FFmpeg 组件...")
        zip_tmp = BIN_DIR / "ffmpeg_win64.zip"
        req = urllib.request.Request(FFMPEG_WIN64_ZIP_URL, headers={"User-Agent": "StreamFetch-Studio/2.3"})
        with urllib.request.urlopen(req, timeout=180) as resp, open(zip_tmp, "wb") as out_f:
            shutil.copyfileobj(resp, out_f)
        with zipfile.ZipFile(zip_tmp, "r") as zf:
            for member in zf.namelist():
                if member.endswith("/bin/ffmpeg.exe") or member.endswith("/bin/ffprobe.exe"):
                    target_name = os.path.basename(member)
                    with zf.open(member) as src_f, open(BIN_DIR / target_name, "wb") as dst_f:
                        shutil.copyfileobj(src_f, dst_f)
        if zip_tmp.exists():
            zip_tmp.unlink()
        if LOCAL_FFMPEG_PATH.exists():
            log_fn(f"✅ [FFmpeg组件] 内置 FFmpeg 已自动安装完成: {LOCAL_FFMPEG_PATH}")
            return str(LOCAL_FFMPEG_PATH)
    except Exception as e:
        log_fn(f"⚠️ [FFmpeg提示] 自动下载 FFmpeg 失败 ({e})，您也可以在终端运行 winget install Gyan.FFmpeg 安装。")
    return resolve_ffmpeg_executable()


def get_local_version(exe_path):
    if not exe_path or not os.path.exists(exe_path):
        return None
    try:
        startupinfo = None
        if IS_WIN:
            startupinfo = subprocess.STARTUPINFO()
            startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
        res = subprocess.run(
            [exe_path, "--version"],
            capture_output=True,
            text=True,
            timeout=10,
            startupinfo=startupinfo
        )
        if res.returncode == 0:
            return res.stdout.strip()
    except Exception:
        pass
    return None


def get_latest_github_version():
    try:
        req = urllib.request.Request(GITHUB_LATEST_API, headers={"User-Agent": "StreamFetch-Studio/2.3"})
        with urllib.request.urlopen(req, timeout=8) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            return data.get("tag_name", "").strip()
    except Exception:
        return None


def ensure_or_update_ytdlp(force_download=False):
    exe = resolve_ytdlp_executable()
    ver = get_local_version(exe)
    latest = get_latest_github_version()
    if force_download or not ver or (latest and latest != ver):
        url = GITHUB_DOWNLOAD_BASE + YTDLP_BIN_NAME
        print(f"[组件管理] 正在从 GitHub 官方源下载内置组件 {YTDLP_BIN_NAME} ...")
        req = urllib.request.Request(url, headers={"User-Agent": "StreamFetch-Studio/2.3"})
        tmp_path = LOCAL_YTDLP_PATH.with_suffix(".tmp")
        with urllib.request.urlopen(req, timeout=120) as resp, open(tmp_path, "wb") as out_f:
            shutil.copyfileobj(resp, out_f)
        if LOCAL_YTDLP_PATH.exists():
            try:
                LOCAL_YTDLP_PATH.unlink()
            except Exception:
                pass
        tmp_path.rename(LOCAL_YTDLP_PATH)
        if not IS_WIN:
            os.chmod(LOCAL_YTDLP_PATH, 0o755)
        exe = str(LOCAL_YTDLP_PATH)
        ver = get_local_version(exe)
        print(f"[组件管理] 内置 yt-dlp 已就绪！当前版本: {ver} ({exe})")
    ensure_ffmpeg_installed()
    return exe, ver, latest or ver


# ==================== 全局下载任务状态与工具函数 ====================
class DownloadState:
    def __init__(self):
        self.lock = threading.Lock()
        self.running = False
        self.percent = 0.0
        self.status = "待命"
        self.logs = []
        self.process = None

    def append_log(self, msg):
        with self.lock:
            self.logs.append(msg)

    def pop_logs(self):
        with self.lock:
            items = list(self.logs)
            self.logs.clear()
            return items


TASK_STATE = DownloadState()


def expand_save_dir(raw_dir):
    if not raw_dir or not str(raw_dir).strip():
        target = DEFAULT_DOWNLOAD_DIR
    else:
        s = str(raw_dir).strip()
        if s.startswith("~"):
            s = os.path.expanduser(s)
        target = Path(s).resolve()
    target.mkdir(parents=True, exist_ok=True)
    return target


def load_json_file(path, default):
    if path.exists():
        try:
            return json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            pass
    return default


def save_json_file(path, data):
    try:
        path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception as e:
        print(f"[保存文件失败] {path}: {e}")


def open_path_in_os(target_path_str):
    raw_str = str(target_path_str or "").strip()
    if raw_str.startswith("~"):
        raw_str = os.path.expanduser(raw_str)
    target = Path(raw_str).resolve() if raw_str else DEFAULT_DOWNLOAD_DIR
    if not target.exists():
        candidate_in_dl = DEFAULT_DOWNLOAD_DIR / target.name
        if candidate_in_dl.exists():
            target = candidate_in_dl.resolve()
        else:
            target = DEFAULT_DOWNLOAD_DIR

    if IS_WIN:
        try:
            ctypes.windll.user32.AllowSetForegroundWindow(-1)
        except Exception:
            pass
        norm_target = os.path.normpath(str(target))
        if target.is_file():
            try:
                ole32 = ctypes.windll.ole32
                shell32 = ctypes.windll.shell32
                ole32.CoInitialize(None)
                shell32.ILCreateFromPathW.argtypes = [ctypes.c_wchar_p]
                shell32.ILCreateFromPathW.restype = ctypes.c_void_p
                shell32.SHOpenFolderAndSelectItems.argtypes = [
                    ctypes.c_void_p, ctypes.c_uint, ctypes.POINTER(ctypes.c_void_p), ctypes.c_ulong
                ]
                shell32.ILFree.argtypes = [ctypes.c_void_p]
                pidl = shell32.ILCreateFromPathW(norm_target)
                if pidl:
                    res = shell32.SHOpenFolderAndSelectItems(pidl, 0, None, 0)
                    shell32.ILFree(pidl)
                    if res == 0:
                        return norm_target
            except Exception:
                pass
            subprocess.Popen(f'explorer.exe /select,"{norm_target}"', shell=True)
            return norm_target
        else:
            target.mkdir(parents=True, exist_ok=True)
            os.startfile(norm_target)
            return norm_target
    elif IS_MAC:
        if target.is_file():
            subprocess.Popen(["open", "-R", str(target)])
        else:
            target.mkdir(parents=True, exist_ok=True)
            subprocess.Popen(["open", str(target)])
        return str(target)
    else:
        folder = target.parent if target.is_file() else target
        folder.mkdir(parents=True, exist_ok=True)
        subprocess.Popen(["xdg-open", str(folder)])
        return str(folder)


def format_file_size(num_bytes):
    if not num_bytes or num_bytes <= 0:
        return "--"
    for unit in ["B", "KB", "MB", "GB"]:
        if num_bytes < 1024.0:
            return f"{num_bytes:.1f} {unit}"
        num_bytes /= 1024.0
    return f"{num_bytes:.2f} TB"


def build_cookie_args():
    cfg = load_json_file(CONFIG_FILE, {})
    mode = cfg.get("cookie_mode", "file" if COOKIES_FILE.exists() else "none")
    if mode == "file" and COOKIES_FILE.exists() and COOKIES_FILE.stat().st_size > 0:
        # 检查是否是假演示 Cookie，若是则不传以免污染请求
        content = COOKIES_FILE.read_text(encoding="utf-8", errors="ignore")
        if "8a92f10c" not in content:
            return ["--cookies", str(COOKIES_FILE)]
    elif mode == "browser":
        browser = cfg.get("cookie_browser", "edge" if IS_WIN else "chrome")
        return ["--cookies-from-browser", browser]
    return []


def run_real_download_worker(payload):
    url = payload.get("url", "").strip()
    quality_label = payload.get("quality", "1080P 高码率 (60帧)")
    fmt = payload.get("format", "bestvideo[height<=1080]+bestaudio/best[height<=1080]")
    raw_save_dir = payload.get("saveDir", str(DEFAULT_DOWNLOAD_DIR))
    embed_subs = bool(payload.get("embedSubs", False))
    playlist = bool(payload.get("playlist", False))

    save_dir = expand_save_dir(raw_save_dir)
    cfg = load_json_file(CONFIG_FILE, {})
    cfg["download_dir"] = str(save_dir)
    save_json_file(CONFIG_FILE, cfg)

    exe = resolve_ytdlp_executable()
    if not exe:
        TASK_STATE.append_log("[组件管理] 正在自动从 GitHub 官方源下载内置 yt-dlp 组件...")
        try:
            exe, _, _ = ensure_or_update_ytdlp(force_download=True)
        except Exception as e:
            TASK_STATE.append_log(f"❌ [错误] 无法下载 yt-dlp 组件: {e}")
            TASK_STATE.status = "失败"
            TASK_STATE.running = False
            return

    # 检查 B站 登录态并给出清晰诊断
    if "bilibili.com" in url or "b23.tv" in url:
        u_info = verify_bilibili_cookie()
        if u_info.get("isLogin"):
            TASK_STATE.append_log(f"✅ [B站身份校验] 已登录账号: {u_info.get('uname')} ({u_info.get('vipLabel')})")
        else:
            TASK_STATE.append_log("⚠️ [重要提示] 当前未配置有效的 B站登录 Cookie！B站对未登录游客最高仅返回 360P/480P 低清流（约几 MB）。如需下载 1080P/4K，请切到「导入 Cookies」页面使用「手机 B站 App 扫码一键登录」！")

    # 确保 FFmpeg 混流器可用（否则 B站 DASH 高清音视频无法合并，只能回退到 360P）
    ffmpeg_exe = ensure_ffmpeg_installed(log_fn=TASK_STATE.append_log)

    cmd = [exe, "--newline", "--no-warnings", "--progress"]
    if ffmpeg_exe:
        cmd.extend(["--ffmpeg-location", str(Path(ffmpeg_exe).parent)])

    cookie_args = build_cookie_args()
    cmd.extend(cookie_args)

    if "仅提取音频" in quality_label:
        if ffmpeg_exe:
            cmd.extend(["-f", "bestaudio/best", "-x", "--audio-format", "mp3"])
        else:
            cmd.extend(["-f", "bestaudio/best"])
    else:
        if ffmpeg_exe:
            cmd.extend(["-f", f"{fmt}/bestvideo+bestaudio/best", "--merge-output-format", "mp4"])
        else:
            TASK_STATE.append_log("⚠️ [缺少FFmpeg] 尚未就绪 FFmpeg，无法合并 B站 DASH 分离高清流，将尝试单文件流下载。")
            cmd.extend(["-f", f"best[ext=mp4]/best/{fmt}"])

    if embed_subs:
        cmd.extend(["--write-subs", "--sub-langs", "zh.*,en.*,-danmaku"])

    cmd.append("--yes-playlist" if playlist else "--no-playlist")

    out_tmpl = str(save_dir / "%(title)s [%(id)s].%(ext)s")
    cmd.extend(["--print", "after_move:filepath", "-o", out_tmpl, url])

    TASK_STATE.append_log(f"$ {' '.join(cmd)}")
    before_files = set(save_dir.glob("*"))
    final_file_path = None
    detected_title = url

    try:
        startupinfo = None
        if IS_WIN:
            startupinfo = subprocess.STARTUPINFO()
            startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW

        proc = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            encoding="utf-8",
            errors="replace",
            startupinfo=startupinfo
        )
        TASK_STATE.process = proc

        for raw_line in proc.stdout:
            line = raw_line.strip()
            if not line:
                continue
            TASK_STATE.append_log(line)

            if "[download]" in line and "%" in line:
                m = re.search(r"(\d+(?:\.\d+)?)%", line)
                if m:
                    try:
                        TASK_STATE.percent = float(m.group(1))
                    except Exception:
                        pass

            if "[download] Destination:" in line:
                dest_str = line.split("[download] Destination:", 1)[1].strip()
                p_cand = Path(dest_str)
                if p_cand.suffix.lower() in MEDIA_EXTENSIONS:
                    final_file_path = p_cand
                    detected_title = p_cand.stem
            elif "[Merger] Merging formats into" in line:
                m_merge = re.search(r'Merging formats into "([^"]+)"', line)
                if m_merge:
                    final_file_path = Path(m_merge.group(1))
                    detected_title = final_file_path.stem
            elif os.path.isabs(line) and os.path.exists(line):
                p_cand = Path(line)
                if p_cand.suffix.lower() in MEDIA_EXTENSIONS:
                    final_file_path = p_cand
                    detected_title = p_cand.stem

        ret = proc.wait()

        # 如果 --cookies-from-browser 因为 Edge/Chrome 独占锁报错，给出明确引导
        cleanup_residual_html_files(save_dir)

        if not final_file_path or not final_file_path.exists() or final_file_path.suffix.lower() not in MEDIA_EXTENSIONS:
            after_files = [
                p for p in (set(save_dir.glob("*")) - before_files)
                if p.is_file() and p.suffix.lower() in MEDIA_EXTENSIONS
            ]
            if not after_files:
                after_files = [
                    p for p in save_dir.glob("*")
                    if p.is_file() and p.suffix.lower() in MEDIA_EXTENSIONS
                ]
            after_files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
            if after_files:
                final_file_path = after_files[0]
                detected_title = final_file_path.stem

        site = "Bilibili" if ("bilibili.com" in url or "b23.tv" in url) else (
            "YouTube" if ("youtube.com" in url or "youtu.be" in url) else "WebVideo"
        )

        history = load_json_file(HISTORY_FILE, [])
        if ret == 0 and final_file_path and final_file_path.exists():
            TASK_STATE.percent = 100.0
            TASK_STATE.status = "已完成"
            fsize_str = format_file_size(final_file_path.stat().st_size)
            saved_target = str(final_file_path.resolve())
            TASK_STATE.append_log(f"✅ [下载成功] 视频已保存至: {saved_target} ({fsize_str})")

            history.insert(0, {
                "id": str(int(time.time() * 1000)),
                "title": detected_title,
                "url": url,
                "site": site,
                "quality": quality_label,
                "size": fsize_str,
                "status": "已完成",
                "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                "savePath": str(save_dir),
                "filePath": saved_target
            })
            save_json_file(HISTORY_FILE, history)
        else:
            TASK_STATE.status = "失败"
            TASK_STATE.append_log(f"❌ [下载未完成] 退出码: {ret}")
    except Exception as e:
        TASK_STATE.status = "错误"
        TASK_STATE.append_log(f"❌ [执行异常] {e}")
    finally:
        TASK_STATE.process = None
        TASK_STATE.running = False


# ==================== HTTP 服务处理器 ====================
class StudioRequestHandler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        pass

    def _read_json(self):
        length = int(self.headers.get("Content-Length", 0))
        if length <= 0:
            return {}
        raw = self.rfile.read(length).decode("utf-8", errors="replace")
        return json.loads(raw)

    def _send_json(self, data, status=200):
        body = json.dumps(data, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if self.path == "/" or self.path.startswith("/index.html"):
            body = EMBEDDED_CANVAS_HTML.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return

        if self.path == "/api/status":
            exe = resolve_ytdlp_executable()
            ver = get_local_version(exe) or "未安装"
            cfg = load_json_file(CONFIG_FILE, {})
            history = load_json_file(HISTORY_FILE, [])
            cookie_text = COOKIES_FILE.read_text(encoding="utf-8", errors="ignore") if COOKIES_FILE.exists() else ""
            bili_user = verify_bilibili_cookie() if cookie_text else {"isLogin": False}
            self._send_json({
                "ok": True,
                "exePath": exe or str(LOCAL_YTDLP_PATH),
                "hasFfmpeg": resolve_ffmpeg_executable() is not None,
                "engineVersion": ver,
                "latestVersion": ver,
                "downloadDir": str(expand_save_dir(cfg.get("download_dir", str(DEFAULT_DOWNLOAD_DIR)))),
                "cookieMode": cfg.get("cookie_mode", "file" if cookie_text else "none"),
                "hasValidCookies": bool(bili_user.get("isLogin")),
                "cookieText": cookie_text,
                "biliUser": bili_user,
                "history": history
            })
            return

        if self.path == "/api/bili-qr-generate":
            try:
                self._send_json(generate_bilibili_qr())
            except Exception as e:
                self._send_json({"ok": False, "error": str(e)})
            return

        if self.path.startswith("/api/bili-qr-poll"):
            qs = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            key = (qs.get("qrcode_key") or [""])[0]
            try:
                self._send_json(poll_bilibili_qr(key))
            except Exception as e:
                self._send_json({"ok": False, "error": str(e)})
            return

        if self.path == "/api/progress":
            history = load_json_file(HISTORY_FILE, []) if not TASK_STATE.running else None
            self._send_json({
                "running": TASK_STATE.running,
                "percent": TASK_STATE.percent,
                "status": TASK_STATE.status,
                "logs": TASK_STATE.pop_logs(),
                "history": history
            })
            return

        self.send_error(404)

    def do_POST(self):
        if self.path == "/api/open-folder":
            data = self._read_json()
            req_path = data.get("path", "")
            rec_id = data.get("id")
            if rec_id:
                history = load_json_file(HISTORY_FILE, [])
                for item in history:
                    if str(item.get("id")) == str(rec_id):
                        req_path = item.get("filePath") or item.get("savePath") or req_path
                        break
            try:
                opened = open_path_in_os(req_path or str(DEFAULT_DOWNLOAD_DIR))
                self._send_json({"ok": True, "openedPath": opened})
            except Exception as e:
                self._send_json({"ok": False, "error": str(e)})
            return

        if self.path == "/api/parse":
            data = self._read_json()
            url = data.get("url", "").strip()
            exe = resolve_ytdlp_executable()
            if not exe:
                try:
                    exe, _, _ = ensure_or_update_ytdlp(force_download=True)
                except Exception as e:
                    self._send_json({"ok": False, "error": str(e)})
                    return
            try:
                cmd = [exe, "--dump-single-json", "--no-playlist", "--no-warnings"]
                cmd.extend(build_cookie_args())
                cmd.append(url)
                res = subprocess.run(cmd, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=25)
                if res.returncode == 0 and res.stdout.strip():
                    info = json.loads(res.stdout.strip().splitlines()[-1])
                    dur_sec = int(info.get("duration") or 0)
                    dur_str = f"{dur_sec // 60:02d}:{dur_sec % 60:02d}" if dur_sec else "未知时长"
                    formats = info.get("formats") or []
                    heights = sorted({f.get("height") for f in formats if f.get("height")}, reverse=True)
                    self._send_json({
                        "ok": True,
                        "heights": " / ".join(f"{h}p" for h in heights[:6]) if heights else "最佳流",
                        "parsed": {
                            "url": url,
                            "site": info.get("extractor_key", "WebVideo"),
                            "bvid": info.get("id", "VID"),
                            "title": info.get("title", url),
                            "uploader": info.get("uploader") or info.get("channel") or "未知作者",
                            "duration": dur_str
                        }
                    })
                else:
                    self._send_json({"ok": False, "error": res.stderr.strip()[:200]})
            except Exception as e:
                self._send_json({"ok": False, "error": str(e)})
            return

        if self.path == "/api/download":
            if TASK_STATE.running:
                self._send_json({"ok": False, "error": "当前已有正在进行的下载任务"})
                return
            payload = self._read_json()
            TASK_STATE.running = True
            TASK_STATE.percent = 0.0
            TASK_STATE.status = "下载中..."
            TASK_STATE.pop_logs()
            threading.Thread(target=run_real_download_worker, args=(payload,), daemon=True).start()
            self._send_json({"ok": True})
            return

        if self.path == "/api/cancel":
            proc = TASK_STATE.process
            if proc:
                try:
                    proc.terminate()
                except Exception:
                    pass
            TASK_STATE.running = False
            TASK_STATE.status = "已取消"
            self._send_json({"ok": True})
            return

        if self.path == "/api/cookies":
            data = self._read_json()
            mode = data.get("cookieMode", "none")
            browser = data.get("cookieBrowser", "edge")
            text = data.get("cookieText", "").strip()
            cfg = load_json_file(CONFIG_FILE, {})
            cfg["cookie_mode"] = mode
            cfg["cookie_browser"] = browser
            save_json_file(CONFIG_FILE, cfg)
            bili_user = {"isLogin": False}
            if mode == "file" and text:
                COOKIES_FILE.write_text(text, encoding="utf-8")
                bili_user = verify_bilibili_cookie()
            elif mode == "none" and COOKIES_FILE.exists():
                try:
                    COOKIES_FILE.unlink()
                except Exception:
                    pass
            self._send_json({"ok": True, "biliUser": bili_user})
            return

        if self.path == "/api/update":
            try:
                exe, ver, _ = ensure_or_update_ytdlp(force_download=True)
                ff = resolve_ffmpeg_executable()
                self._send_json({
                    "ok": True,
                    "version": ver or "最新版",
                    "exePath": exe,
                    "ffmpegStatus": f"已就绪 ({ff})" if ff else "未安装"
                })
            except Exception as e:
                self._send_json({"ok": False, "error": str(e)})
            return

        self.send_error(404)


def find_free_port(start_port=8765):
    for port in range(start_port, start_port + 50):
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            if s.connect_ex(("127.0.0.1", port)) != 0:
                return port
    return 8765


def scan_existing_downloads_into_history():
    cleanup_residual_html_files(DEFAULT_DOWNLOAD_DIR)
    history = load_json_file(HISTORY_FILE, [])
    existing_paths = {item.get("filePath") for item in history if item.get("filePath")}

    for f in sorted(DEFAULT_DOWNLOAD_DIR.glob("*"), key=lambda p: p.stat().st_mtime, reverse=True):
        if f.is_file() and f.suffix.lower() in MEDIA_EXTENSIONS:
            full_str = str(f.resolve())
            if full_str not in existing_paths:
                history.append({
                    "id": str(int(f.stat().st_mtime * 1000)),
                    "title": f.stem,
                    "url": "本地已下载视频",
                    "site": "Bilibili" if "BV" in f.stem else "WebVideo",
                    "quality": "本地视频",
                    "size": format_file_size(f.stat().st_size),
                    "status": "已完成",
                    "timestamp": datetime.fromtimestamp(f.stat().st_mtime).strftime("%Y-%m-%d %H:%M:%S"),
                    "savePath": str(DEFAULT_DOWNLOAD_DIR),
                    "filePath": full_str
                })
    save_json_file(HISTORY_FILE, history)


def main():
    print("=" * 74)
    print("  🎬 StreamFetch Studio — 基于 yt-dlp 的视频下载工作台 (v2.3 扫码登录+FFmpeg版)")
    print("=" * 74)
    cleanup_fake_demo_cookie()
    scan_existing_downloads_into_history()
    threading.Thread(target=ensure_or_update_ytdlp, daemon=True).start()

    port = find_free_port(8765)
    url = f"http://127.0.0.1:{port}"
    server = HTTPServer(("127.0.0.1", port), StudioRequestHandler)

    print(f"  📂 默认视频下载保存位置: {DEFAULT_DOWNLOAD_DIR}")
    print(f"  ✅ 本地服务已启动: {url}")
    print("  📱 请在网页「导入 Cookies」页点击【手机 B站 App 扫码一键登录】获取真实大会员/1080P权限！")
    print("=" * 74)

    threading.Timer(0.6, lambda: webbrowser.open(url)).start()
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\n[已退出] 感谢使用 StreamFetch Studio！")
        server.server_close()


if __name__ == "__main__":
    main()
